  'cups': {meaning:['Dengan n gelas, tinggi tumpukan dalam cm adalah:','For n glasses, the stack’s height in cm is:'],equation:'16 + 5(n − 1)'},
  'headphones': {meaning:['Jika h adalah nilai headphone, upah harian yang sama memberi:','If h is the headphones’ value, equal daily pay gives:'],equation:'(h + 960) ÷ 24 = (h + 660) ÷ 18'},
